import React, { Component } from 'react'
import NewsItem from './NewsItem'

export class News extends Component {
    constructor(){
        super();
        console.log("Hello I am a constructor from News Component");
        this.state = {
            articles: [],
            loading: false,
            page: 1
        }
    }
    handelPrevious=()=>{
      console.log("Previous");
    }
    handelNext=()=>{
      console.log("Next");
      this.state({
        page: this.state.page+1,
      })
    }
  render() {
    return (
      <div className='container my-3'>
        <h1>Velocity News Top Headlines</h1>
        <div className="row">
        {this.state.articles.map((element)=>{
            
            return <div className="col-md-4" key={element.url} >
            <NewsItem title={element.title?element.title.slice(0,45):""} description={element.description?element.description.slice(0,88):""} imageUrl={element.urlToImage} newsUrl={element.url}/>
        </div>
        })} 
        </div>
        <div className='container d-flex justify-content-between'>
        <button disabled={this.state.page<=1} type="button" class="btn btn-dark" onClick={this.handelPrevious}> &larr; Previous</button>
        <button type="button" class="btn btn-dark" onClick={this.handelNext}>Next &rarr;</button>
        </div>
      </div>
    )
  }
}

export default News
